func syncSliceValues[A, B any](values []A, convert func(A) B) []B {
	if values == nil {
		return nil
	}
	out := make([]B, len(values))
	for i, value := range values {
		out[i] = convert(value)
	}
	return out
}
func syncMapValues[K comparable, V any, L comparable, W any](values map[K]V, convert func(K, V) (L, W)) map[L]W {
	if values == nil {
		return nil
	}
	out := make(map[L]W, len(values))
	for key, value := range values {
		k, v := convert(key, value)
		out[k] = v
	}
	return out
}
